#!/usr/bin/env sh
# Stills, words only on top of SolidCraft's renders (video/make_frames.py) and our drawings of the OSM data
# (video/map_png.py). Needs ffmpeg + DejaVu fonts (the video-qa image):
#   docker run --rm -v <lab>:/work -w /work video-qa:2 sh video/make_hook.sh
#   hook-landscape.png  the drawing imported with no unit (red) beside the one that says millimetres, same camera, north
#                       arrows on the floor; content at 88% inside a margin (the 5 s push-in never crops a word)
#   data-picture.png    the plate, north up, graph paper every 10 m, the OSM credit in the corner
#   grid-picture.png    the Flatiron on 1 m graph paper: the hand count
#   north-picture.png   map / our model / north left as screen-down: which way the narrow end points
#   hook-vertical.png   the Short's frame 0
#   pair-labelled.png   chapter 2 card: the two imports with their words
#   block-labelled.png  chapter 4 card: the block, the Flatiron named
set -eu
F=video/frames
B=/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf
R=/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf
RED=0xb71c1c; GREEN=0x1b5e20; INK=0x1f2937; GREY=0x475569; BG=0xeceff4
N=$(python3 -c "import json;print(json.load(open('out/evidence/numbers.json'))['squares'])" 2>/dev/null || echo "")
ffmpeg -v error -y -i $F/pair-iso.png -filter_complex "[0:v]crop=1000:820:470:120,scale=1080:-2[a];color=c=$BG:s=1920x1080[bg];[bg][a]overlay=420:150,drawtext=fontfile=$B:text='✗ A QUARTER AS WIDE':fontcolor=$RED:fontsize=60:x=90:y=40,drawtext=fontfile=$R:text='drawing with no unit':fontcolor=$RED:fontsize=38:x=90:y=118,drawtext=fontfile=$B:text='✓ RIGHT SIZE':fontcolor=$GREEN:fontsize=60:x=w-text_w-90:y=40,drawtext=fontfile=$R:text='drawing says mm':fontcolor=$GREEN:fontsize=38:x=w-text_w-90:y=118,drawtext=fontfile=$B:text='N':fontcolor=$INK:fontsize=40:x=870:y=880,drawtext=fontfile=$B:text='N':fontcolor=$INK:fontsize=40:x=1170:y=968,drawtext=fontfile=$R:text='The Flatiron Building from OpenStreetMap · both 86 mm tall · SolidCraft 0.19.0 renders, same camera · arrows\: north':fontcolor=$INK:fontsize=26:x=(w-text_w)/2:y=1030,drawtext=fontfile=$R:text='© OpenStreetMap contributors':fontcolor=$GREY:fontsize=24:x=w-text_w-24:y=990,scale=1690:950,pad=1920:1080:115:65:color=$BG" -frames:v 1 $F/hook-landscape.png
ffmpeg -v error -y -i $F/data-map.png -filter_complex "[0:v]scale=1140:855[a];color=c=0xffffff:s=1920x1080[bg];[bg][a]overlay=390:110,drawtext=fontfile=$B:text='N ↑':fontcolor=$INK:fontsize=64:x=170:y=130,drawtext=fontfile=$R:text='big square = 10 m x 10 m':fontcolor=$GREY:fontsize=32:x=120:y=240,drawtext=fontfile=$B:text='Flatiron':fontcolor=$INK:fontsize=34:x=870:y=480,drawtext=fontfile=$B:text='Buildings from OpenStreetMap, north up, on graph paper':fontcolor=$INK:fontsize=44:x=(w-text_w)/2:y=32,drawtext=fontfile=$R:text='© OpenStreetMap contributors · openstreetmap.org/copyright':fontcolor=$GREY:fontsize=28:x=w-text_w-40:y=1010,drawtext=fontfile=$R:text='our drawing of the data · 120 x 90 m':fontcolor=$GREY:fontsize=28:x=40:y=1010" -frames:v 1 $F/data-picture.png
ffmpeg -v error -y -i $F/grid-count.png -filter_complex "[0:v]scale=-2:1000[a];color=c=0xffffff:s=1920x1080[bg];[bg][a]overlay=580:40,drawtext=fontfile=$B:text='Count the squares':fontcolor=$INK:fontsize=54:x=80:y=200,drawtext=fontfile=$R:text='1 square = 1 m x 1 m':fontcolor=$INK:fontsize=38:x=80:y=290,drawtext=fontfile=$B:text='$N squares':fontcolor=0x1d4ed8:fontsize=54:x=80:y=420,drawtext=fontfile=$R:text='= about 1,000 m² of floor':fontcolor=$INK:fontsize=38:x=80:y=500,drawtext=fontfile=$R:text='= 1,000 mm² at 1 \: 1000':fontcolor=$INK:fontsize=38:x=80:y=560,drawtext=fontfile=$B:text='N ↑':fontcolor=$INK:fontsize=56:x=1580:y=60,drawtext=fontfile=$R:text='© OpenStreetMap contributors':fontcolor=$GREY:fontsize=26:x=w-text_w-30:y=1040" -frames:v 1 $F/grid-picture.png
ffmpeg -v error -y -i $F/north-map.png -i $F/north-model.png -i $F/north-mirror.png -filter_complex "[0:v]scale=560:560[a];[1:v]scale=560:560[b];[2:v]scale=560:560[c];color=c=0xffffff:s=1920x1080[bg];[bg][a]overlay=60:250[t];[t][b]overlay=680:250[u];[u][c]overlay=1300:250,drawbox=x=60:y=250:w=560:h=560:color=0xd1d5db:t=3,drawbox=x=680:y=250:w=560:h=560:color=0xd1d5db:t=3,drawbox=x=1300:y=250:w=560:h=560:color=0xd1d5db:t=3,drawtext=fontfile=$B:text='THE MAP':fontcolor=$INK:fontsize=46:x=60+(560-text_w)/2:y=150,drawtext=fontfile=$B:text='✓ OUR MODEL':fontcolor=$GREEN:fontsize=46:x=680+(560-text_w)/2:y=150,drawtext=fontfile=$B:text='✗ NORTH FLIPPED':fontcolor=$RED:fontsize=46:x=1300+(560-text_w)/2:y=150,drawtext=fontfile=$R:text='narrow end\: 11.6°':fontcolor=$INK:fontsize=36:x=60+(560-text_w)/2:y=840,drawtext=fontfile=$R:text='narrow end\: 11.6°':fontcolor=$GREEN:fontsize=36:x=680+(560-text_w)/2:y=840,drawtext=fontfile=$R:text='narrow end\: 168.4°':fontcolor=$RED:fontsize=36:x=1300+(560-text_w)/2:y=840,drawtext=fontfile=$B:text='N ↑':fontcolor=$INK:fontsize=56:x=40:y=40,drawtext=fontfile=$R:text='Seen from above, north up · arrow\: from the middle to the narrow end · degrees clockwise from north':fontcolor=$INK:fontsize=28:x=(w-text_w)/2:y=940,drawtext=fontfile=$R:text='© OpenStreetMap contributors':fontcolor=$GREY:fontsize=24:x=w-text_w-24:y=1040" -frames:v 1 $F/north-picture.png
ffmpeg -v error -y -i $F/pair-front.png -filter_complex "[0:v]crop=760:700:600:170,scale=1000:-2[a];color=c=$BG:s=1080x1920[bg];[bg][a]overlay=40:520,drawtext=fontfile=$B:text='How many times':fontcolor=$INK:fontsize=76:x=(w-text_w)/2:y=170,drawtext=fontfile=$B:text='narrower?':fontcolor=$INK:fontsize=76:x=(w-text_w)/2:y=265,drawtext=fontfile=$B:text='2, 4 or 8':fontcolor=0x1d4ed8:fontsize=84:x=(w-text_w)/2:y=380,drawtext=fontfile=$B:text='✗ imported':fontcolor=$RED:fontsize=50:x=90:y=1480,drawtext=fontfile=$B:text='✓ the real size':fontcolor=$GREEN:fontsize=50:x=w-text_w-70:y=1480,drawtext=fontfile=$R:text='The Flatiron from OpenStreetMap · SolidCraft renders':fontcolor=$INK:fontsize=34:x=(w-text_w)/2:y=1800,drawtext=fontfile=$R:text='© OpenStreetMap contributors':fontcolor=$GREY:fontsize=30:x=(w-text_w)/2:y=1850" -frames:v 1 $F/hook-vertical.png
ffmpeg -v error -y -i $F/pair-front.png -filter_complex "drawtext=fontfile=$B:text='✗ no unit':fontcolor=$RED:fontsize=56:x=560:y=110,drawtext=fontfile=$B:text='✓ says mm':fontcolor=$GREEN:fontsize=56:x=930:y=110,drawtext=fontfile=$R:text='both 86 mm tall · SolidCraft 0.19.0 render · © OpenStreetMap contributors':fontcolor=$INK:fontsize=30:x=(w-text_w)/2:y=990" -frames:v 1 $F/pair-labelled.png
ffmpeg -v error -y -i $F/block-iso.png -filter_complex "drawtext=fontfile=$B:text='Flatiron':fontcolor=$INK:fontsize=56:x=870:y=90,drawtext=fontfile=$B:text='120 x 90 mm plate · 11 buildings · one piece':fontcolor=$INK:fontsize=44:x=(w-text_w)/2:y=930,drawtext=fontfile=$R:text='SolidCraft 0.19.0 render · © OpenStreetMap contributors':fontcolor=$GREY:fontsize=28:x=(w-text_w)/2:y=1000" -frames:v 1 $F/block-labelled.png
echo "wrote hook-landscape.png data-picture.png grid-picture.png north-picture.png hook-vertical.png"
